//! The simulated world: your database, the network, the provider, the clock and the crash injector, and the
//! NDJSON log they write. Course-supplied harness (LAB-8.4 to LAB-8.7); you do not edit this file.
//!
//! The harness owns every choice: which message moves next, when a timer fires, when the worker crashes, which
//! reply is delivered twice. It asks your fault plan (`faults.rs`) to make each choice from the seeded `Rng`, so a
//! run is a function of your machine and the seed. Your machine (`machine.rs`) sees only `Input`s and answers
//! with `Output`s; the harness carries the outputs out, one at a time, and may crash the worker between two.
//!
//! The log is trace@1 (labs/LAB-8/README.md): one JSON object per line, at the grain of the spec's actions,
//! derived from what the harness did to the database and the network:
//!
//!   {"event":"Commit","cmd":"c1"}                          the client's transaction committed command and intent
//!   {"event":"Dispatch","cmd":"c1","key":["c1",0],"att":1}  a request left, carrying a key and an attempt number
//!   {"event":"Timeout","cmd":"c1"}                          an inflight intent went back to pending, to be sent again
//!   {"event":"TimerArmed","cmd":"c1"}                       a timer was armed (no spec variable changes)
//!   {"event":"Receive","cmd":"c1"}                          the worker took a reply in
//!   {"event":"Persist","cmd":"c1"}                          the provider's result was stored
//!   {"event":"Ack","cmd":"c1"}                              the intent was marked done
//!   {"event":"Crash"}  {"event":"Recover"}                  the worker stopped, and restarted
//!   {"event":"End"}                                         the run ended normally (written last)
//!
//! The provider's own steps are not logged: TLC searches for them.

use crate::faults::{self, Choice, Menu};
use crate::machine::Machine;
use std::collections::{BTreeMap, BTreeSet};

/// A command's name, such as "c1".
pub type Cmd = String;

/// An idempotency key: the command and a number. One key per intent is `Key { cmd, n: 0 }`, which the log writes
/// as `["c1",0]`.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Key {
    pub cmd: Cmd,
    pub n: u32,
}

/// The intent the client's transaction committed with its command, with the key minted at commit.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Intent {
    pub cmd: Cmd,
    pub key: Key,
}

/// A reply from the provider: the request it answers.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Reply {
    pub cmd: Cmd,
    pub key: Key,
    pub att: u32,
}

/// An outbox row as your database holds it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Status {
    Pending,
    Inflight,
    Acked,
}

/// One outbox row, as the harness hands it to a restarted machine: what is durable.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Row {
    pub cmd: Cmd,
    pub key: Key,
    /// requests made so far for this intent
    pub att: u32,
    pub status: Status,
    /// whether the provider's result is stored
    pub stored: bool,
}

/// Everything your machine learns arrives as an input.
#[derive(Clone, Debug)]
pub enum Input {
    /// The client's transaction committed this command and its intent.
    Commit(Intent),
    /// The timer armed for this command fired.
    Tick(Cmd),
    /// A reply arrived. It may be late, duplicated, or for an earlier attempt.
    Reply(Reply),
    /// The worker restarted after a crash. Its memory is empty; these are the durable rows.
    Restarted(Vec<Row>),
}

/// Everything your machine does is an output, which the harness carries out.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Output {
    /// Send a request for the command with this key; `att` is the attempt number, 1 for the first.
    Send { cmd: Cmd, key: Key, att: u32 },
    /// Store the provider's result for the command (durable).
    Store(Cmd),
    /// Mark the command's intent done (durable).
    Ack(Cmd),
    /// Arm a timer for the command.
    Arm(Cmd),
}

/// SplitMix64: the only source of choice in a run.
#[derive(Clone, Debug)]
pub struct Rng(u64);

impl Rng {
    pub fn new(seed: u64) -> Rng {
        Rng(seed)
    }
    pub fn next_u64(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }
    /// A number in 0..n (n > 0).
    pub fn below(&mut self, n: u64) -> u64 {
        assert!(n > 0, "below(0)");
        self.next_u64() % n
    }
}

/// Seeded mutations the harness can apply to your machine's outputs, for LAB-8.6 and LAB-8.7.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Mutant {
    None,
    /// The intent is marked done before the provider's result is stored (LAB-8.6, SP-8.4).
    AckBeforeStore,
    /// Every attempt carries a fresh key (LAB-8.7's planted failure, SP-8.3).
    FreshKey,
    /// After a restart, a stored intent is sent again before it is acknowledged (Prove-it, LAB-8.4).
    ResendStored,
}

impl Mutant {
    pub fn parse(s: &str) -> Option<Mutant> {
        match s {
            "none" => Some(Mutant::None),
            "ack-before-store" => Some(Mutant::AckBeforeStore),
            "fresh-key" => Some(Mutant::FreshKey),
            "resend-stored" => Some(Mutant::ResendStored),
            _ => None,
        }
    }
}

/// The run's parameters.
#[derive(Clone, Debug)]
pub struct Config {
    pub seed: u64,
    /// faults per thousand choices
    pub rate: u32,
    /// the step cap of the faulty phase; a fault-free drain follows
    pub steps: u32,
    pub commands: u32,
    pub max_crashes: u32,
    pub max_ticks: u32,
    pub max_dups: u32,
    pub mutant: Mutant,
    /// systematic mode: crash once, the first time c1 is in this window ("CW1" to "CW4"); no other fault
    pub crash_in: Option<&'static str>,
}

impl Config {
    pub fn new(seed: u64) -> Config {
        Config { seed, rate: 150, steps: 200, commands: 2, max_crashes: 2, max_ticks: 2, max_dups: 3, mutant: Mutant::None, crash_in: None }
    }
}

/// The first property a run broke.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Violation {
    /// the harness step at which it was seen (1-based)
    pub step: u32,
    /// the log line count when it was seen
    pub line: usize,
    /// NoDoubleCharge, AckedIsDurable, NoLostIntent or Liveness
    pub property: &'static str,
    pub detail: String,
}

/// What a run produced.
#[derive(Clone, Debug)]
pub struct Outcome {
    pub log: Vec<String>,
    pub steps: u32,
    pub crashes: u32,
    pub ticks: u32,
    pub dups: u32,
    pub violation: Option<Violation>,
}

impl Outcome {
    pub fn ndjson(&self) -> String {
        let mut s = String::new();
        for l in &self.log {
            s.push_str(l);
            s.push('\n');
        }
        s
    }
    pub fn faults(&self) -> u32 {
        self.crashes + self.ticks + self.dups
    }
}

struct DbRow {
    key: Key,
    att: u32,
    status: Status,
    stored: bool,
}

struct SentReply {
    reply: Reply,
    delivered: bool,
}

struct World {
    cfg: Config,
    rng: Rng,
    machine: Option<Machine>,
    db: BTreeMap<Cmd, DbRow>,
    to_commit: Vec<Cmd>,
    reqs: Vec<Reply>, // requests in flight: [cmd, key, att]
    replies: Vec<SentReply>,
    seen: BTreeSet<Key>,
    charges: BTreeMap<Cmd, u32>,
    armed: BTreeSet<Cmd>,
    crashes: u32,
    ticks: u32,
    dups: u32,
    step: u32,
    log: Vec<String>,
    violation: Option<Violation>,
    crashed_in_window: bool,
}

fn key_json(k: &Key) -> String {
    format!("[\"{}\",{}]", k.cmd, k.n)
}

#[derive(Clone, Debug)]
enum Event {
    Commit(Cmd),
    Accept(usize),
    Deliver(usize),
    Restart,
    Crash,
    Tick(Cmd),
    Duplicate(usize),
}

impl World {
    fn new(cfg: Config) -> World {
        let to_commit = (1..=cfg.commands).map(|i| format!("c{i}")).collect();
        World {
            rng: Rng::new(cfg.seed),
            cfg,
            machine: Some(Machine::new()),
            db: BTreeMap::new(),
            to_commit,
            reqs: Vec::new(),
            replies: Vec::new(),
            seen: BTreeSet::new(),
            charges: BTreeMap::new(),
            armed: BTreeSet::new(),
            crashes: 0,
            ticks: 0,
            dups: 0,
            step: 0,
            log: Vec::new(),
            violation: None,
            crashed_in_window: false,
        }
    }

    fn emit(&mut self, line: String) {
        self.log.push(line);
    }

    fn fail(&mut self, property: &'static str, detail: String) {
        if self.violation.is_none() {
            self.violation = Some(Violation { step: self.step, line: self.log.len(), property, detail });
        }
    }

    fn up(&self) -> bool {
        self.machine.is_some()
    }

    /// Safety, after every sub-step.
    fn monitor(&mut self) {
        let doubled: Vec<(Cmd, u32)> = self.charges.iter().filter(|(_, n)| **n > 1).map(|(c, n)| (c.clone(), *n)).collect();
        if let Some((c, n)) = doubled.first() {
            self.fail("NoDoubleCharge", format!("the provider charged {c} {n} times"));
        }
        let early: Vec<Cmd> = self.db.iter().filter(|(_, r)| r.status == Status::Acked && !r.stored).map(|(c, _)| c.clone()).collect();
        if let Some(c) = early.first() {
            self.fail("AckedIsDurable", format!("{c} was acknowledged before its result was stored"));
        }
    }

    /// The window c1 is in now (curriculum section 1.2), for systematic mode.
    fn window_of(&self, c: &str) -> Option<&'static str> {
        let row = self.db.get(c)?;
        let replied = self.replies.iter().any(|r| r.reply.cmd == c);
        let in_flight = self.reqs.iter().any(|r| r.cmd == c);
        match row.status {
            Status::Acked => None,
            Status::Pending => Some("CW1"),
            Status::Inflight if row.stored => Some("CW4"),
            Status::Inflight if replied => Some("CW3"),
            Status::Inflight if in_flight => Some("CW2"),
            Status::Inflight => None,
        }
    }

    fn crash_allowed(&self) -> bool {
        self.up() && self.crashes < self.cfg.max_crashes && self.db.values().any(|r| r.status != Status::Acked)
    }

    /// A point between two sub-steps where the worker may crash. Returns true when it crashed.
    fn checkpoint(&mut self, faulty: bool) -> bool {
        self.monitor();
        if !self.up() {
            return false;
        }
        if let Some(w) = self.cfg.crash_in {
            if !self.crashed_in_window && self.window_of("c1") == Some(w) {
                self.crashed_in_window = true;
                self.crash();
                return true;
            }
            return false;
        }
        if faulty && self.crash_allowed() {
            let menu = Menu { normal: 1, faults: 1, rate: self.cfg.rate };
            if let Choice::Fault(_) = faults::choose(&mut self.rng, &menu) {
                self.crash();
                return true;
            }
        }
        false
    }

    fn crash(&mut self) {
        self.machine = None;
        self.armed.clear();
        self.crashes += 1;
        self.emit("{\"event\":\"Crash\"}".into());
    }

    fn mutate(&self, outs: Vec<Output>, restarted: bool) -> Vec<Output> {
        match self.cfg.mutant {
            Mutant::None => outs,
            Mutant::ResendStored if !restarted => outs,
            Mutant::ResendStored => outs
                .into_iter()
                .flat_map(|o| match o {
                    Output::Ack(c) => match self.db.get(&c) {
                        Some(r) if r.stored => vec![Output::Send { cmd: c.clone(), key: r.key.clone(), att: r.att + 1 }, Output::Arm(c.clone()), Output::Ack(c)],
                        _ => vec![Output::Ack(c)],
                    },
                    other => vec![other],
                })
                .collect(),
            Mutant::FreshKey => outs
                .into_iter()
                .map(|o| match o {
                    Output::Send { cmd, key, att } => Output::Send { key: Key { cmd: key.cmd, n: att }, cmd, att },
                    other => other,
                })
                .collect(),
            Mutant::AckBeforeStore => {
                let mut outs = outs;
                for i in 0..outs.len() {
                    if let Output::Store(c) = outs[i].clone() {
                        if let Some(j) = (i + 1..outs.len()).find(|&j| outs[j] == Output::Ack(c.clone())) {
                            outs.swap(i, j);
                        }
                    }
                }
                outs
            }
        }
    }

    /// Under the fresh-key mutation the machine sent a key it never minted; its reply comes back under the
    /// intent's own key, as if the machine kept the key it sent.
    fn unmutate(&self, mut r: Reply) -> Reply {
        if self.cfg.mutant == Mutant::FreshKey {
            if let Some(row) = self.db.get(&r.cmd) {
                r.key = row.key.clone();
            }
        }
        r
    }

    /// Feed one input to the machine and carry out its outputs, one at a time, with a crash point after each.
    fn feed(&mut self, input: Input, faulty: bool) {
        let is_reply = matches!(input, Input::Reply(_));
        let restarted = matches!(input, Input::Restarted(_));
        let reply_cmd = if let Input::Reply(r) = &input { Some(r.cmd.clone()) } else { None };
        let outs = match self.machine.as_mut() {
            Some(m) => m.step(input),
            None => return,
        };
        let outs = self.mutate(outs, restarted);
        if is_reply && !outs.is_empty() {
            let c = reply_cmd.unwrap_or_default();
            self.emit(format!("{{\"event\":\"Receive\",\"cmd\":\"{c}\"}}"));
            if self.checkpoint(faulty) {
                return;
            }
        }
        for out in outs {
            self.carry_out(out);
            if self.checkpoint(faulty) {
                return;
            }
        }
    }

    fn carry_out(&mut self, out: Output) {
        match out {
            Output::Send { cmd, key, att } => {
                let Some(row) = self.db.get_mut(&cmd) else {
                    self.fail("NoLostIntent", format!("the machine sent {cmd}, which no committed intent names"));
                    return;
                };
                let resend = row.status != Status::Pending;
                row.status = Status::Inflight;
                row.att = att;
                if resend {
                    self.emit(format!("{{\"event\":\"Timeout\",\"cmd\":\"{cmd}\"}}"));
                }
                self.emit(format!("{{\"event\":\"Dispatch\",\"cmd\":\"{cmd}\",\"key\":{},\"att\":{att}}}", key_json(&key)));
                self.reqs.push(Reply { cmd, key, att });
            }
            Output::Arm(cmd) => {
                self.armed.insert(cmd.clone());
                self.emit(format!("{{\"event\":\"TimerArmed\",\"cmd\":\"{cmd}\"}}"));
            }
            Output::Store(cmd) => {
                if let Some(row) = self.db.get_mut(&cmd) {
                    row.stored = true;
                }
                self.emit(format!("{{\"event\":\"Persist\",\"cmd\":\"{cmd}\"}}"));
            }
            Output::Ack(cmd) => {
                if let Some(row) = self.db.get_mut(&cmd) {
                    row.status = Status::Acked;
                }
                self.armed.remove(&cmd);
                self.emit(format!("{{\"event\":\"Ack\",\"cmd\":\"{cmd}\"}}"));
            }
        }
    }

    fn rows(&self) -> Vec<Row> {
        self.db.iter().map(|(c, r)| Row { cmd: c.clone(), key: r.key.clone(), att: r.att, status: r.status, stored: r.stored }).collect()
    }

    fn normal_events(&self) -> Vec<Event> {
        let mut ev = Vec::new();
        if let Some(c) = self.to_commit.first() {
            ev.push(Event::Commit(c.clone()));
        }
        for i in 0..self.reqs.len() {
            ev.push(Event::Accept(i));
        }
        if self.up() {
            for (i, r) in self.replies.iter().enumerate() {
                if !r.delivered {
                    ev.push(Event::Deliver(i));
                }
            }
        } else {
            ev.push(Event::Restart);
        }
        ev
    }

    fn fault_events(&self) -> Vec<Event> {
        let mut ev = Vec::new();
        if self.cfg.crash_in.is_some() {
            return ev;
        }
        if self.crash_allowed() {
            ev.push(Event::Crash);
        }
        if self.up() && self.ticks < self.cfg.max_ticks {
            for c in &self.armed {
                if self.db.get(c).map(|r| r.status == Status::Inflight && !r.stored).unwrap_or(false) {
                    ev.push(Event::Tick(c.clone()));
                }
            }
        }
        if self.up() && self.dups < self.cfg.max_dups {
            for (i, r) in self.replies.iter().enumerate() {
                if r.delivered {
                    ev.push(Event::Duplicate(i));
                }
            }
        }
        ev
    }

    fn apply(&mut self, e: Event, faulty: bool) {
        match e {
            Event::Commit(c) => {
                self.to_commit.retain(|x| *x != c);
                let key = Key { cmd: c.clone(), n: 0 };
                self.db.insert(c.clone(), DbRow { key: key.clone(), att: 0, status: Status::Pending, stored: false });
                self.emit(format!("{{\"event\":\"Commit\",\"cmd\":\"{c}\"}}"));
                if self.checkpoint(faulty) {
                    return;
                }
                self.feed(Input::Commit(Intent { cmd: c, key }), faulty);
            }
            Event::Accept(i) => {
                let r = self.reqs.remove(i);
                if !self.seen.contains(&r.key) {
                    *self.charges.entry(r.cmd.clone()).or_insert(0) += 1;
                }
                self.seen.insert(r.key.clone());
                self.replies.push(SentReply { reply: r, delivered: false });
                self.checkpoint(faulty);
            }
            Event::Deliver(i) => {
                self.replies[i].delivered = true;
                let r = self.unmutate(self.replies[i].reply.clone());
                self.feed(Input::Reply(r), faulty);
            }
            Event::Duplicate(i) => {
                self.dups += 1;
                let r = self.unmutate(self.replies[i].reply.clone());
                self.feed(Input::Reply(r), faulty);
            }
            Event::Tick(c) => {
                self.ticks += 1;
                self.armed.remove(&c);
                self.feed(Input::Tick(c), faulty);
            }
            Event::Crash => {
                self.crash();
            }
            Event::Restart => {
                self.emit("{\"event\":\"Recover\"}".into());
                for row in self.db.values_mut() {
                    if row.status == Status::Inflight && !row.stored {
                        row.status = Status::Pending;
                    }
                }
                self.machine = Some(Machine::new());
                if self.checkpoint(faulty) {
                    return;
                }
                let rows = self.rows();
                self.feed(Input::Restarted(rows), faulty);
            }
        }
    }

    fn run(mut self) -> Outcome {
        // the faulty phase: your fault plan makes every choice
        while self.step < self.cfg.steps {
            let normal = self.normal_events();
            let fault = self.fault_events();
            if normal.is_empty() {
                break; // nothing ordinary is left to do: the run is over, whatever faults are still possible
            }
            self.step += 1;
            let menu = Menu { normal: normal.len(), faults: fault.len(), rate: if self.cfg.crash_in.is_some() { 0 } else { self.cfg.rate } };
            let e = match faults::choose(&mut self.rng, &menu) {
                Choice::Normal(i) if i < normal.len() => normal[i].clone(),
                Choice::Fault(i) if i < fault.len() => fault[i].clone(),
                Choice::Normal(_) | Choice::Fault(_) => normal[0].clone(),
            };
            self.apply(e, true);
        }
        // the drain: no faults, the first enabled event each time, until nothing is left to do
        let mut drained = 0;
        while drained < 1000 {
            let normal = self.normal_events();
            let Some(e) = normal.first().cloned() else { break };
            self.step += 1;
            drained += 1;
            self.apply(e, false);
        }
        if self.violation.is_none() {
            let left: Vec<Cmd> = self.db.iter().filter(|(_, r)| r.status != Status::Acked).map(|(c, _)| c.clone()).collect();
            if let Some(c) = left.first() {
                self.fail("NoLostIntent", format!("{c} was committed and never acknowledged: its intent was left behind"));
            } else if !self.to_commit.is_empty() {
                self.fail("NoLostIntent", "a command was never committed".into());
            }
        }
        // the run ended normally, whatever it broke on the way: the log is complete
        self.emit("{\"event\":\"End\"}".into());
        Outcome { steps: self.step, crashes: self.crashes, ticks: self.ticks, dups: self.dups, violation: self.violation, log: self.log }
    }
}

/// Run your machine once under the configuration's seed and fault plan.
pub fn run(cfg: Config) -> Outcome {
    World::new(cfg).run()
}

/// SHA-256 of a byte string (FIPS 180-4), so a trace's hash prints without a crate.
pub fn sha256_hex(data: &[u8]) -> String {
    const K: [u32; 64] = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe,
        0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
        0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
        0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
    ];
    let mut h: [u32; 8] = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
    let mut msg = data.to_vec();
    let bits = (data.len() as u64).wrapping_mul(8);
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&bits.to_be_bytes());
    for chunk in msg.chunks(64) {
        let mut w = [0u32; 64];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([chunk[4 * i], chunk[4 * i + 1], chunk[4 * i + 2], chunk[4 * i + 3]]);
        }
        for i in 16..64 {
            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16].wrapping_add(s0).wrapping_add(w[i - 7]).wrapping_add(s1);
        }
        let mut v = h;
        for i in 0..64 {
            let s1 = v[4].rotate_right(6) ^ v[4].rotate_right(11) ^ v[4].rotate_right(25);
            let ch = (v[4] & v[5]) ^ (!v[4] & v[6]);
            let t1 = v[7].wrapping_add(s1).wrapping_add(ch).wrapping_add(K[i]).wrapping_add(w[i]);
            let s0 = v[0].rotate_right(2) ^ v[0].rotate_right(13) ^ v[0].rotate_right(22);
            let maj = (v[0] & v[1]) ^ (v[0] & v[2]) ^ (v[1] & v[2]);
            let t2 = s0.wrapping_add(maj);
            v = [t1.wrapping_add(t2), v[0], v[1], v[2], v[3].wrapping_add(t1), v[4], v[5], v[6]];
        }
        for i in 0..8 {
            h[i] = h[i].wrapping_add(v[i]);
        }
    }
    h.iter().map(|x| format!("{x:08x}")).collect()
}
